<?php
declare(strict_types=1);

function stock_column_exists(string $table, string $column): bool
{
    $s = database()->prepare('SELECT COUNT(*) FROM information_schema.columns WHERE table_schema=DATABASE() AND table_name=:table_name AND column_name=:column_name');
    $s->execute(['table_name' => $table, 'column_name' => $column]);
    return (bool) $s->fetchColumn();
}

function ensure_stock_tables(): void
{
    static $ready = false;
    if ($ready) return;
    ensure_suppliers_table();
    $pdo = database();
    $pdo->exec("CREATE TABLE IF NOT EXISTS stock_items (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, part_code VARCHAR(60) NOT NULL, part_name VARCHAR(190) NOT NULL, category VARCHAR(100) NULL, brand VARCHAR(100) NULL, unit VARCHAR(30) NOT NULL DEFAULT 'PCS', buying_price DECIMAL(12,2) NOT NULL DEFAULT 0, selling_price DECIMAL(12,2) NOT NULL DEFAULT 0, stock_qty DECIMAL(12,2) NOT NULL DEFAULT 0, reorder_level DECIMAL(12,2) NOT NULL DEFAULT 10, supplier_id BIGINT UNSIGNED NULL, status ENUM('active','inactive') NOT NULL DEFAULT 'active', notes TEXT NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, PRIMARY KEY (id), UNIQUE KEY stock_items_code_unique (part_code), KEY stock_items_category_index (category), KEY stock_items_brand_index (brand), KEY stock_items_qty_index (stock_qty), CONSTRAINT stock_items_supplier_fk FOREIGN KEY (supplier_id) REFERENCES suppliers (id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
    $pdo->exec("CREATE TABLE IF NOT EXISTS stock_purchases (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, purchase_no VARCHAR(30) NOT NULL, supplier_id BIGINT UNSIGNED NULL, purchase_date DATE NOT NULL, invoice_no VARCHAR(80) NULL, payment_status ENUM('paid','due','partial') NOT NULL DEFAULT 'paid', total_amount DECIMAL(12,2) NOT NULL DEFAULT 0, status ENUM('received','cancelled') NOT NULL DEFAULT 'received', notes TEXT NULL, created_by BIGINT UNSIGNED NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, updated_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP, PRIMARY KEY (id), UNIQUE KEY stock_purchases_no_unique (purchase_no), KEY stock_purchases_date_index (purchase_date), KEY stock_purchases_supplier_index (supplier_id), CONSTRAINT stock_purchases_supplier_fk FOREIGN KEY (supplier_id) REFERENCES suppliers (id) ON DELETE SET NULL, CONSTRAINT stock_purchases_user_fk FOREIGN KEY (created_by) REFERENCES users (id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
    foreach ([
        ['invoice_no', "ALTER TABLE stock_purchases ADD invoice_no VARCHAR(80) NULL AFTER purchase_date"],
        ['payment_status', "ALTER TABLE stock_purchases ADD payment_status ENUM('paid','due','partial') NOT NULL DEFAULT 'paid' AFTER invoice_no"],
        ['created_by', "ALTER TABLE stock_purchases ADD created_by BIGINT UNSIGNED NULL AFTER notes"],
        ['paid_amount', "ALTER TABLE stock_purchases ADD paid_amount DECIMAL(12,2) NOT NULL DEFAULT 0 AFTER payment_status"],
        ['balance_amount', "ALTER TABLE stock_purchases ADD balance_amount DECIMAL(12,2) NOT NULL DEFAULT 0 AFTER paid_amount"],
    ] as [$column, $sql]) if (!stock_column_exists('stock_purchases', $column)) $pdo->exec($sql);
    $pdo->exec("CREATE TABLE IF NOT EXISTS stock_purchase_items (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, purchase_id BIGINT UNSIGNED NOT NULL, stock_item_id BIGINT UNSIGNED NOT NULL, quantity DECIMAL(12,2) NOT NULL DEFAULT 0, unit_cost DECIMAL(12,2) NOT NULL DEFAULT 0, amount DECIMAL(12,2) NOT NULL DEFAULT 0, buying_price DECIMAL(12,2) NOT NULL DEFAULT 0, selling_price DECIMAL(12,2) NULL, line_total DECIMAL(12,2) NOT NULL DEFAULT 0, PRIMARY KEY (id), KEY stock_purchase_items_purchase_index (purchase_id), KEY stock_purchase_items_stock_index (stock_item_id), CONSTRAINT stock_purchase_items_purchase_fk FOREIGN KEY (purchase_id) REFERENCES stock_purchases (id) ON DELETE CASCADE, CONSTRAINT stock_purchase_items_stock_fk FOREIGN KEY (stock_item_id) REFERENCES stock_items (id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
    foreach ([
        ['buying_price', "ALTER TABLE stock_purchase_items ADD buying_price DECIMAL(12,2) NOT NULL DEFAULT 0 AFTER unit_cost"],
        ['selling_price', "ALTER TABLE stock_purchase_items ADD selling_price DECIMAL(12,2) NULL AFTER buying_price"],
        ['line_total', "ALTER TABLE stock_purchase_items ADD line_total DECIMAL(12,2) NOT NULL DEFAULT 0 AFTER amount"],
    ] as [$column, $sql]) if (!stock_column_exists('stock_purchase_items', $column)) $pdo->exec($sql);
    $pdo->exec("CREATE TABLE IF NOT EXISTS stock_batches (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, stock_item_id BIGINT UNSIGNED NOT NULL, stock_purchase_item_id BIGINT UNSIGNED NULL, quantity_received DECIMAL(12,2) NOT NULL, quantity_remaining DECIMAL(12,2) NOT NULL, buying_price DECIMAL(12,2) NOT NULL, selling_price_at_purchase DECIMAL(12,2) NULL, purchase_date DATE NOT NULL, supplier_id BIGINT UNSIGNED NULL, batch_reference VARCHAR(80) NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY (id), KEY stock_batches_item_index (stock_item_id), KEY stock_batches_purchase_item_index (stock_purchase_item_id), KEY stock_batches_date_index (purchase_date), KEY stock_batches_reference_index (batch_reference), CONSTRAINT stock_batches_item_fk FOREIGN KEY (stock_item_id) REFERENCES stock_items (id) ON DELETE CASCADE, CONSTRAINT stock_batches_purchase_item_fk FOREIGN KEY (stock_purchase_item_id) REFERENCES stock_purchase_items (id) ON DELETE SET NULL, CONSTRAINT stock_batches_supplier_fk FOREIGN KEY (supplier_id) REFERENCES suppliers (id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
    $pdo->exec("CREATE TABLE IF NOT EXISTS stock_movements (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, stock_item_id BIGINT UNSIGNED NOT NULL, movement_type ENUM('opening_stock','restock','job_usage','sale','adjustment_in','adjustment_out','return') NOT NULL, quantity DECIMAL(12,2) NOT NULL, quantity_before DECIMAL(12,2) NOT NULL DEFAULT 0, quantity_after DECIMAL(12,2) NOT NULL DEFAULT 0, unit_cost DECIMAL(12,2) NOT NULL DEFAULT 0, reference_type VARCHAR(40) NULL, reference_id BIGINT UNSIGNED NULL, notes TEXT NULL, created_by BIGINT UNSIGNED NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY (id), KEY stock_movements_item_index (stock_item_id), KEY stock_movements_type_index (movement_type), KEY stock_movements_reference_index (reference_type,reference_id), KEY stock_movements_created_index (created_at), CONSTRAINT stock_movements_item_fk FOREIGN KEY (stock_item_id) REFERENCES stock_items (id) ON DELETE CASCADE, CONSTRAINT stock_movements_user_fk FOREIGN KEY (created_by) REFERENCES users (id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
    $pdo->exec("CREATE TABLE IF NOT EXISTS stock_batch_consumptions (id BIGINT UNSIGNED NOT NULL AUTO_INCREMENT, stock_item_id BIGINT UNSIGNED NOT NULL, stock_batch_id BIGINT UNSIGNED NOT NULL, reference_type VARCHAR(40) NOT NULL, reference_id BIGINT UNSIGNED NULL, quantity DECIMAL(12,2) NOT NULL, unit_cost DECIMAL(12,2) NOT NULL, total_cost DECIMAL(12,2) NOT NULL, created_at DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP, PRIMARY KEY (id), KEY stock_batch_consumptions_item_index (stock_item_id), KEY stock_batch_consumptions_batch_index (stock_batch_id), CONSTRAINT stock_batch_consumptions_item_fk FOREIGN KEY (stock_item_id) REFERENCES stock_items (id) ON DELETE CASCADE, CONSTRAINT stock_batch_consumptions_batch_fk FOREIGN KEY (stock_batch_id) REFERENCES stock_batches (id) ON DELETE CASCADE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci");
    $pdo->exec("INSERT INTO stock_batches (stock_item_id,quantity_received,quantity_remaining,buying_price,selling_price_at_purchase,purchase_date,supplier_id,batch_reference) SELECT si.id,si.stock_qty,si.stock_qty,si.buying_price,si.selling_price,CURDATE(),si.supplier_id,CONCAT('OPEN-',LPAD(si.id,4,'0')) FROM stock_items si LEFT JOIN stock_batches sb ON sb.stock_item_id=si.id WHERE si.stock_qty>0 AND sb.id IS NULL");
    $pdo->exec("INSERT INTO stock_movements (stock_item_id,movement_type,quantity,quantity_before,quantity_after,unit_cost,reference_type,reference_id,notes) SELECT si.id,'opening_stock',si.stock_qty,0,si.stock_qty,si.buying_price,'stock_item',si.id,'Opening stock migrated from existing stock record' FROM stock_items si LEFT JOIN stock_movements sm ON sm.stock_item_id=si.id WHERE si.stock_qty>0 AND sm.id IS NULL");
    $ready = true;
}

function stock_suppliers(): array { return database()->query("SELECT id,name,supplier_code FROM suppliers WHERE status='active' ORDER BY name")->fetchAll(); }
function stock_categories(): array { return database()->query("SELECT DISTINCT category FROM stock_items WHERE category IS NOT NULL AND category<>'' ORDER BY category")->fetchAll(PDO::FETCH_COLUMN); }
function stock_brands(): array { return database()->query("SELECT DISTINCT brand FROM stock_items WHERE brand IS NOT NULL AND brand<>'' ORDER BY brand")->fetchAll(PDO::FETCH_COLUMN); }
function stock_item(int $id): ?array { $s=database()->prepare('SELECT si.*,s.name supplier_name,COALESCE((SELECT SUM(sb.quantity_remaining*sb.buying_price)/NULLIF(SUM(sb.quantity_remaining),0) FROM stock_batches sb WHERE sb.stock_item_id=si.id),si.buying_price) average_cost FROM stock_items si LEFT JOIN suppliers s ON s.id=si.supplier_id WHERE si.id=:id LIMIT 1');$s->execute(['id'=>$id]);return $s->fetch()?:null; }
function stock_items(array $f=[]): array { $w=["si.status='active'"];$p=[];if(($f['search']??'')!==''){$w[]='(si.part_code LIKE :q OR si.part_name LIKE :q OR si.brand LIKE :q OR si.category LIKE :q)';$p['q']='%'.$f['search'].'%';}if(($f['category']??'')!==''){$w[]='si.category=:category';$p['category']=$f['category'];}if(($f['brand']??'')!==''){$w[]='si.brand=:brand';$p['brand']=$f['brand'];}if(($f['status']??'')==='low')$w[]='si.stock_qty<=si.reorder_level AND si.stock_qty>0';elseif(($f['status']??'')==='out')$w[]='si.stock_qty<=0';elseif(($f['status']??'')==='in')$w[]='si.stock_qty>si.reorder_level';$where=$w?' WHERE '.implode(' AND ',$w):'';$s=database()->prepare("SELECT si.*,s.name supplier_name,COALESCE((SELECT SUM(sb.quantity_remaining*sb.buying_price)/NULLIF(SUM(sb.quantity_remaining),0) FROM stock_batches sb WHERE sb.stock_item_id=si.id),si.buying_price) average_cost FROM stock_items si LEFT JOIN suppliers s ON s.id=si.supplier_id{$where} ORDER BY si.id DESC");$s->execute($p);return $s->fetchAll(); }
function stock_summary(): array { $r=database()->query("SELECT COUNT(*) total,SUM(stock_qty>reorder_level) in_stock,SUM(stock_qty>0 AND stock_qty<=reorder_level) low_stock,SUM(stock_qty<=0) out_stock,COALESCE(SUM(stock_qty*buying_price),0) inventory_value FROM stock_items WHERE status='active'")->fetch()?:[];return ['total'=>(int)($r['total']??0),'in_stock'=>(int)($r['in_stock']??0),'low_stock'=>(int)($r['low_stock']??0),'out_stock'=>(int)($r['out_stock']??0),'inventory_value'=>(float)($r['inventory_value']??0)]; }
function stock_input(?array $source=null): array { $source??=$_POST;return ['existing_stock_id'=>max(0,(int)($source['existing_stock_id']??0)),'part_code'=>trim((string)($source['part_code']??'')),'part_name'=>trim((string)($source['part_name']??'')),'category'=>trim((string)($source['category']??'')),'brand'=>trim((string)($source['brand']??'')),'unit'=>trim((string)($source['unit']??'PCS')),'buying_price'=>(string)($source['buying_price']??'0'),'selling_price'=>(string)($source['selling_price']??'0'),'stock_qty'=>(string)($source['stock_qty']??'0'),'reorder_level'=>(string)($source['reorder_level']??'10'),'supplier_id'=>max(0,(int)($source['supplier_id']??0)),'status'=>in_array($source['status']??'', ['active','inactive'],true)?$source['status']:'active','notes'=>trim((string)($source['notes']??''))]; }
function validate_stock(array $i,int $id=0): array { $e=[];if($i['part_code']==='')$e[]='Part code is required.';if($i['part_name']==='')$e[]='Part name is required.';if((float)$i['buying_price']<0||(float)$i['selling_price']<0||(float)$i['stock_qty']<0||(float)$i['reorder_level']<0)$e[]='Prices and quantities cannot be negative.';$s=database()->prepare('SELECT id FROM stock_items WHERE part_code=:code AND id<>:id');$s->execute(['code'=>$i['part_code'],'id'=>$id]);if($s->fetchColumn())$e[]='This part code already exists.';return $e; }
function purchase_rows(array $filters=[]): array { $where=[];$params=[];if(($filters['date_from']??'')!==''){$where[]='p.purchase_date>=:date_from';$params['date_from']=$filters['date_from'];}if(($filters['date_to']??'')!==''){$where[]='p.purchase_date<=:date_to';$params['date_to']=$filters['date_to'];}if(in_array($filters['payment_status']??'', ['paid','partial','due'],true)){$where[]='p.payment_status=:payment_status';$params['payment_status']=$filters['payment_status'];}$sql='SELECT p.*,s.name supplier_name,u.name created_by_name,(SELECT COUNT(*) FROM stock_purchase_items pi WHERE pi.purchase_id=p.id) item_count FROM stock_purchases p LEFT JOIN suppliers s ON s.id=p.supplier_id LEFT JOIN users u ON u.id=p.created_by'.($where?' WHERE '.implode(' AND ',$where):'').' ORDER BY p.purchase_date DESC,p.id DESC';$s=database()->prepare($sql);$s->execute($params);return $s->fetchAll(); }
function purchase_items(int $id): array { $s=database()->prepare('SELECT pi.*,si.part_code,si.part_name FROM stock_purchase_items pi JOIN stock_items si ON si.id=pi.stock_item_id WHERE pi.purchase_id=:id');$s->execute(['id'=>$id]);return $s->fetchAll(); }
function purchase_input(?array $source=null): array { $source??=$_POST;$items=[];foreach((array)($source['items']??[]) as $item){if((int)($item['stock_item_id']??0)>0)$items[]=['stock_item_id'=>(int)$item['stock_item_id'],'quantity'=>(string)($item['quantity']??'1'),'unit_cost'=>(string)($item['unit_cost']??'0')];}return ['supplier_id'=>max(0,(int)($source['supplier_id']??0)),'purchase_date'=>trim((string)($source['purchase_date']??date('Y-m-d'))),'invoice_no'=>trim((string)($source['invoice_no']??'')),'payment_status'=>in_array($source['payment_status']??'', ['paid','due','partial'],true)?$source['payment_status']:'paid','notes'=>trim((string)($source['notes']??'')),'items'=>$items]; }
function restock_input(): array { $source=$_SERVER['REQUEST_METHOD']==='POST'?$_POST:$_GET;return ['stock_item_id'=>max(0,(int)($source['stock_item_id']??0)),'quantity'=>(string)($source['quantity']??''),'buying_price'=>(string)($source['buying_price']??''),'selling_price'=>trim((string)($source['selling_price']??'')),'supplier_id'=>max(0,(int)($source['supplier_id']??0)),'paid_amount'=>(string)($source['paid_amount']??'0'),'purchase_date'=>trim((string)($source['purchase_date']??date('Y-m-d'))),'invoice_no'=>trim((string)($source['invoice_no']??'')),'payment_status'=>in_array($source['payment_status']??'', ['paid','due','partial'],true)?$source['payment_status']:'paid','notes'=>trim((string)($source['notes']??''))]; }
function stock_batches(int $id): array { $s=database()->prepare('SELECT sb.*,s.name supplier_name,sp.purchase_no,sp.invoice_no FROM stock_batches sb LEFT JOIN suppliers s ON s.id=sb.supplier_id LEFT JOIN stock_purchase_items pi ON pi.id=sb.stock_purchase_item_id LEFT JOIN stock_purchases sp ON sp.id=pi.purchase_id WHERE sb.stock_item_id=:id ORDER BY sb.purchase_date ASC,sb.id ASC');$s->execute(['id'=>$id]);return $s->fetchAll(); }
function stock_movements(int $id): array { $s=database()->prepare('SELECT sm.*,u.name user_name FROM stock_movements sm LEFT JOIN users u ON u.id=sm.created_by WHERE sm.stock_item_id=:id ORDER BY sm.created_at DESC,sm.id DESC');$s->execute(['id'=>$id]);return $s->fetchAll(); }
function movement_label(string $type): string { return ucwords(str_replace('_',' ',$type)); }
function stock_average(int $id, float $qty, float $cost): float { $s=database()->prepare('SELECT COALESCE(SUM(quantity_remaining*buying_price),0) FROM stock_batches WHERE stock_item_id=:id');$s->execute(['id'=>$id]);$value=(float)$s->fetchColumn();return $qty>0?($value/$qty):$cost; }
function consume_stock_fifo(int $stockItemId, float $quantity, string $referenceType, ?int $referenceId=null, ?int $userId=null, string $notes=''): float
{
    if ($quantity <= 0) throw new InvalidArgumentException('Consumption quantity must be greater than zero.');
    $pdo=database();$pdo->beginTransaction();
    try {
        $item=$pdo->prepare('SELECT * FROM stock_items WHERE id=:id FOR UPDATE');$item->execute(['id'=>$stockItemId]);$stock=$item->fetch();if(!$stock)throw new RuntimeException('Stock item not found.');
        $available=(float)$stock['stock_qty'];if($quantity>$available)throw new RuntimeException('Insufficient stock available.');
        $remaining=$quantity;$costTotal=0.0;$batches=$pdo->prepare('SELECT * FROM stock_batches WHERE stock_item_id=:id AND quantity_remaining>0 ORDER BY purchase_date ASC,id ASC FOR UPDATE');$batches->execute(['id'=>$stockItemId]);$consumption=$pdo->prepare('INSERT INTO stock_batch_consumptions (stock_item_id,stock_batch_id,reference_type,reference_id,quantity,unit_cost,total_cost) VALUES (:item,:batch,:type,:ref,:qty,:cost,:total)');$reduce=$pdo->prepare('UPDATE stock_batches SET quantity_remaining=quantity_remaining-:qty WHERE id=:id AND quantity_remaining>=:qty');
        foreach($batches as $batch){if($remaining<=0)break;$taken=min($remaining,(float)$batch['quantity_remaining']);$reduce->execute(['qty'=>$taken,'id'=>$batch['id']]);if($reduce->rowCount()!==1)throw new RuntimeException('Stock batch could not be updated.');$cost=(float)$batch['buying_price'];$consumption->execute(['item'=>$stockItemId,'batch'=>$batch['id'],'type'=>$referenceType,'ref'=>$referenceId,'qty'=>$taken,'cost'=>$cost,'total'=>$taken*$cost]);$costTotal+=$taken*$cost;$remaining-=$taken;}
        if($remaining>0.00001)throw new RuntimeException('Stock batches are inconsistent with total stock.');$after=$available-$quantity;$movement=$pdo->prepare("INSERT INTO stock_movements (stock_item_id,movement_type,quantity,quantity_before,quantity_after,unit_cost,reference_type,reference_id,notes,created_by) VALUES (:item,:type,:qty,:before,:after,:cost,:ref_type,:ref_id,:notes,:user)");$movementType=in_array($referenceType,['job_usage','sale','adjustment_out'],true)?$referenceType:'job_usage';$movement->execute(['item'=>$stockItemId,'type'=>$movementType,'qty'=>$quantity,'before'=>$available,'after'=>$after,'cost'=>$quantity>0?$costTotal/$quantity:0,'ref_type'=>$referenceType,'ref_id'=>$referenceId,'notes'=>$notes?:'FIFO stock consumption','user'=>$userId]);$pdo->prepare('UPDATE stock_items SET stock_qty=:qty WHERE id=:id')->execute(['qty'=>$after,'id'=>$stockItemId]);$pdo->commit();return $costTotal;
    } catch(Throwable $e) { if($pdo->inTransaction())$pdo->rollBack();throw $e; }
}
function stock_create_opening(PDO $pdo,int $itemId,float $qty,float $cost,string $date,?int $userId): void { if($qty<=0)return;$s=$pdo->prepare('INSERT INTO stock_batches (stock_item_id,quantity_received,quantity_remaining,buying_price,selling_price_at_purchase,purchase_date,batch_reference) VALUES (:item,:qty,:remaining,:cost,NULL,:date,:ref)');$s->execute(['item'=>$itemId,'qty'=>$qty,'remaining'=>$qty,'cost'=>$cost,'date'=>$date,'ref'=>'OPEN-'.str_pad((string)$itemId,4,'0',STR_PAD_LEFT)]);$m=$pdo->prepare("INSERT INTO stock_movements (stock_item_id,movement_type,quantity,quantity_before,quantity_after,unit_cost,reference_type,reference_id,notes,created_by) VALUES (:item,'opening_stock',:qty,0,:after,:cost,'stock_item',:ref,:notes,:user)");$m->execute(['item'=>$itemId,'qty'=>$qty,'after'=>$qty,'cost'=>$cost,'ref'=>$itemId,'notes'=>'Opening stock','user'=>$userId]); }
function restock_save(array $input, array &$errors): bool { $errors=[];$date=DateTime::createFromFormat('Y-m-d',$input['purchase_date']);$qty=(float)$input['quantity'];$cost=(float)$input['buying_price'];$total=$qty*$cost;$paidAmount=$input['payment_status']==='paid'?$total:($input['payment_status']==='due'?0:(float)($input['paid_amount']??0));if($input['stock_item_id']<=0)$errors[]='Select an existing stock item.';if($qty<=0)$errors[]='Quantity received must be greater than zero.';if($cost<0)$errors[]='Buying price cannot be negative.';if($paidAmount<0||$paidAmount>$total)$errors[]='Paid amount must be between zero and the total purchase amount.';if(!$date||$date->format('Y-m-d')!==$input['purchase_date'])$errors[]='Select a valid purchase date.';if($errors)return false;$pdo=database();$pdo->beginTransaction();try{$s=$pdo->prepare('SELECT * FROM stock_items WHERE id=:id FOR UPDATE');$s->execute(['id'=>$input['stock_item_id']]);$item=$s->fetch();if(!$item)throw new RuntimeException('Stock item not found.');$before=(float)$item['stock_qty'];$after=$before+$qty;$average=($before*(float)$item['buying_price']+$qty*$cost)/$after;$selling=$input['selling_price']===''?(float)$item['selling_price']:(float)$input['selling_price'];$p=$pdo->prepare("INSERT INTO stock_purchases (purchase_no,supplier_id,purchase_date,invoice_no,payment_status,paid_amount,balance_amount,total_amount,status,notes,created_by) VALUES (:no,:supplier,:date,:invoice,:payment,:paid,:balance,:total,'received',:notes,:user)");$p->execute(['no'=>'TMP-'.bin2hex(random_bytes(4)),'supplier'=>$input['supplier_id']?:null,'date'=>$input['purchase_date'],'invoice'=>$input['invoice_no']?:null,'payment'=>$input['payment_status'],'paid'=>$paidAmount,'balance'=>$total-$paidAmount,'total'=>$total,'notes'=>$input['notes']?:null,'user'=>current_user()['id']??null]);$purchaseId=(int)$pdo->lastInsertId();$purchaseNo='PUR-'.date('ymd',strtotime($input['purchase_date'])).'-'.str_pad((string)$purchaseId,4,'0',STR_PAD_LEFT);$pdo->prepare('UPDATE stock_purchases SET purchase_no=:no WHERE id=:id')->execute(['no'=>$purchaseNo,'id'=>$purchaseId]);$pi=$pdo->prepare('INSERT INTO stock_purchase_items (purchase_id,stock_item_id,quantity,unit_cost,amount,buying_price,selling_price,line_total) VALUES (:purchase,:item,:qty,:cost,:amount,:cost,:selling,:amount)');$pi->execute(['purchase'=>$purchaseId,'item'=>$input['stock_item_id'],'qty'=>$qty,'cost'=>$cost,'amount'=>$qty*$cost,'selling'=>$selling]);$purchaseItemId=(int)$pdo->lastInsertId();$ref='BATCH-'.str_pad((string)$purchaseItemId,4,'0',STR_PAD_LEFT);$b=$pdo->prepare('INSERT INTO stock_batches (stock_item_id,stock_purchase_item_id,quantity_received,quantity_remaining,buying_price,selling_price_at_purchase,purchase_date,supplier_id,batch_reference) VALUES (:item,:purchase_item,:qty,:qty,:cost,:selling,:date,:supplier,:ref)');$b->execute(['item'=>$input['stock_item_id'],'purchase_item'=>$purchaseItemId,'qty'=>$qty,'cost'=>$cost,'selling'=>$selling,'date'=>$input['purchase_date'],'supplier'=>$input['supplier_id']?:null,'ref'=>$ref]);$m=$pdo->prepare("INSERT INTO stock_movements (stock_item_id,movement_type,quantity,quantity_before,quantity_after,unit_cost,reference_type,reference_id,notes,created_by) VALUES (:item,'restock',:qty,:before,:after,:cost,'stock_purchase',:ref,:notes,:user)");$m->execute(['item'=>$input['stock_item_id'],'qty'=>$qty,'before'=>$before,'after'=>$after,'cost'=>$cost,'ref'=>$purchaseId,'notes'=>$input['notes']?:'Stock restock','user'=>current_user()['id']??null]);$pdo->prepare('UPDATE stock_items SET stock_qty=:qty,buying_price=:average,selling_price=:selling,supplier_id=:supplier WHERE id=:id')->execute(['qty'=>$after,'average'=>$average,'selling'=>$selling,'supplier'=>$input['supplier_id']?:$item['supplier_id'],'id'=>$input['stock_item_id']]);$pdo->commit();return true;}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$errors[]=$e->getMessage()==='Stock item not found.'?$e->getMessage():'Restock could not be saved. Please try again.';return false;} }
function stock_purchase(int $id): ?array { $s=database()->prepare('SELECT p.*,s.name supplier_name,u.name created_by_name FROM stock_purchases p LEFT JOIN suppliers s ON s.id=p.supplier_id LEFT JOIN users u ON u.id=p.created_by WHERE p.id=:id LIMIT 1');$s->execute(['id'=>$id]);return $s->fetch()?:null; }
function stock_purchase_update(int $id, array $input, array &$errors): bool { $errors=[];$date=DateTime::createFromFormat('Y-m-d',$input['purchase_date']);$total=(float)$input['total_amount'];$paid=(float)$input['paid_amount'];if(!$date||$date->format('Y-m-d')!==$input['purchase_date'])$errors[]='Select a valid purchase date.';if($paid<0||$paid>$total)$errors[]='Paid amount must be between zero and total amount.';if($errors)return false;$status=$paid<=0?'due':($paid>=$total?'paid':'partial');$s=database()->prepare('UPDATE stock_purchases SET supplier_id=:supplier,purchase_date=:date,payment_status=:status,paid_amount=:paid,balance_amount=:balance,notes=:notes WHERE id=:id');$s->execute(['supplier'=>$input['supplier_id']?:null,'date'=>$input['purchase_date'],'status'=>$status,'paid'=>$paid,'balance'=>$total-$paid,'notes'=>$input['notes']?:null,'id'=>$id]);return true; }
function stock_purchase_payment(int $id, float $amount, array &$errors): bool { $errors=[];$p=stock_purchase($id);if(!$p){$errors[]='Purchase not found.';return false;}$balance=(float)$p['balance_amount'];if($amount<=0||$amount>$balance){$errors[]='Payment must be greater than zero and cannot exceed the remaining balance.';return false;}$paid=(float)$p['paid_amount']+$amount;$total=(float)$p['total_amount'];$status=$paid>=$total?'paid':'partial';$s=database()->prepare('UPDATE stock_purchases SET paid_amount=:paid,balance_amount=:balance,payment_status=:status WHERE id=:id');$s->execute(['paid'=>$paid,'balance'=>max(0,$total-$paid),'status'=>$status,'id'=>$id]);return true; }
function handle_stock_request(string $section): void
{
    ensure_stock_tables();$id=max(0,(int)($_GET['id']??$_POST['stock_id']??$_POST['purchase_id']??0));$errors=[];
    if(in_array($section,['stock-purchase-view','stock-purchase-edit','stock-purchase-pay','stock-purchase-delete'],true)){$purchase=stock_purchase($id);if(!$purchase){http_response_code(404);exit('Purchase not found.');}if($section==='stock-purchase-delete'&&$_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$s=database()->prepare("UPDATE stock_purchases SET status='cancelled' WHERE id=:id");$s->execute(['id'=>$id]);flash('success','Purchase marked as cancelled.');redirect('index.php?page=admin&section=stock-purchases');}if($section==='stock-purchase-pay'){$amount=(float)($_POST['payment_amount']??0);if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();if(stock_purchase_payment($id,$amount,$errors)){flash('success','Payment recorded successfully.');redirect('index.php?page=admin&section=stock-purchases');}}$title='Pay Stock Purchase';$sectionForHeader='stock-purchases';require __DIR__.'/../includes/header.php';require __DIR__.'/../views/stock-purchase-pay.php';require __DIR__.'/../includes/footer.php';return;}if($section==='stock-purchase-edit'){$editInput=['supplier_id'=>(int)($purchase['supplier_id']??0),'purchase_date'=>$purchase['purchase_date'],'total_amount'=>$purchase['total_amount'],'paid_amount'=>$purchase['paid_amount']??0,'notes'=>$purchase['notes']??''];if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$editInput=['supplier_id'=>max(0,(int)($_POST['supplier_id']??0)),'purchase_date'=>trim((string)($_POST['purchase_date']??'')),'total_amount'=>$purchase['total_amount'],'paid_amount'=>(string)($_POST['paid_amount']??0),'notes'=>trim((string)($_POST['notes']??''))];if(stock_purchase_update($id,$editInput,$errors)){flash('success','Purchase payment details updated.');redirect('index.php?page=admin&section=stock-purchases');}}$suppliers=stock_suppliers();$title='Edit Purchase';$sectionForHeader='stock-purchases';require __DIR__.'/../includes/header.php';require __DIR__.'/../views/stock-purchase-edit.php';require __DIR__.'/../includes/footer.php';return;} $purchaseItems=purchase_items($id);$title='View Purchase';$sectionForHeader='stock-purchases';require __DIR__.'/../includes/header.php';require __DIR__.'/../views/stock-purchase-view.php';require __DIR__.'/../includes/footer.php';return;}
    if($section==='stock-delete'&&$_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$s=database()->prepare("UPDATE stock_items SET status='inactive' WHERE id=:id");$s->execute(['id'=>$id]);flash('success','Stock item marked inactive.');redirect('index.php?page=admin&section=stock');}
