    if(in_array($section,['stock-add','stock-edit'],true)){$input=stock_input();if($section==='stock-edit'&&$_SERVER['REQUEST_METHOD']!=='POST'){$input=stock_item($id)?:[];if(!$input){http_response_code(404);exit('Stock item not found.');}}if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$input=stock_input();$targetId=$section==='stock-edit'?$id:$input['existing_stock_id'];$errors=validate_stock($input,$targetId);if(!$errors){$pdo=database();$pdo->beginTransaction();try{$v=['part_code'=>$input['part_code'],'part_name'=>$input['part_name'],'category'=>$input['category']?:null,'brand'=>$input['brand']?:null,'unit'=>$input['unit']?:'PCS','buying_price'=>(float)$input['buying_price'],'selling_price'=>(float)$input['selling_price'],'stock_qty'=>(float)$input['stock_qty'],'reorder_level'=>(float)$input['reorder_level'],'supplier_id'=>$input['supplier_id']?:null,'status'=>$input['status'],'notes'=>$input['notes']?:null];if($section==='stock-add'&&$targetId===0){$s=$pdo->prepare('INSERT INTO stock_items (part_code,part_name,category,brand,unit,buying_price,selling_price,stock_qty,reorder_level,supplier_id,status,notes) VALUES (:part_code,:part_name,:category,:brand,:unit,:buying_price,:selling_price,:stock_qty,:reorder_level,:supplier_id,:status,:notes)');$s->execute($v);$newId=(int)$pdo->lastInsertId();stock_create_opening($pdo,$newId,$v['stock_qty'],$v['buying_price'],date('Y-m-d'),current_user()['id']??null);flash('success','Stock item added successfully.');}else{$v['id']=$targetId;$s=$pdo->prepare('UPDATE stock_items SET part_code=:part_code,part_name=:part_name,category=:category,brand=:brand,unit=:unit,buying_price=:buying_price,selling_price=:selling_price,stock_qty=:stock_qty,reorder_level=:reorder_level,supplier_id=:supplier_id,status=:status,notes=:notes WHERE id=:id');$s->execute($v);flash('success','Stock item updated successfully.');}$pdo->commit();redirect('index.php?page=admin&section=stock');}catch(Throwable $e){if($pdo->inTransaction())$pdo->rollBack();$errors[]='Stock item could not be saved.';}}}$suppliers=stock_suppliers();$stockOptions=database()->query('SELECT id,part_code,part_name,category,brand,unit,buying_price,selling_price,stock_qty,reorder_level,supplier_id,status,notes FROM stock_items ORDER BY part_name')->fetchAll();$title=$section==='stock-edit'?'Edit Stock':'Add Stock';$sectionForHeader=$section;require __DIR__.'/../includes/header.php';require __DIR__.'/../views/stock-form.php';require __DIR__.'/../includes/footer.php';return;}
